// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

struct PairMaxOiAndFundingFeeConfig {
    uint256 maxLongOiUsd;
    uint256 maxShortOiUsd;
    uint256 fundingFeePerBlockP;
    uint256 minFundingFeeR;
    uint256 maxFundingFeeR;
